{"description": "Read README, echo marker, catch missing-file error", "code": "const summary = { readOk: false, bashOk: false, errorMessage: null };

try {
  const r = await tools.read({ file_path: "README.md", limit: 3 });
  summary.readOk = Array.isArray(r.lines) && r.lines.length > 0;
} catch (e) {
  summary.readOk = false;
}

try {
  const b = await tools.bash({ command: "echo ptc-fixture-ok", description: "Print the fixture marker" });
  summary.bashOk = b.kind === "foreground" && b.exitCode === 0 && String(b.stdout.text).includes("ptc-fixture-ok");
} catch (e) {
  summary.bashOk = false;
}

try {
  await tools.read({ file_path: "ptc-missing-file.txt", limit: 3 });
} catch (e) {
  summary.errorMessage = String((e && e.message) || e);
}

return summary;"}
